package com.dongqh.luckyhub.scheduler.fulfillment;
import com.dongqh.luckyhub.config.fulfillment.FulfillmentProperties;import com.dongqh.luckyhub.service.fulfillment.FulfillmentStateService;import com.dongqh.luckyhub.worker.fulfillment.FulfillmentWorker;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class FulfillmentScheduler {private final FulfillmentStateService state;private final FulfillmentWorker worker;private final FulfillmentProperties properties;public FulfillmentScheduler(FulfillmentStateService state,FulfillmentWorker worker,FulfillmentProperties properties){this.state=state;this.worker=worker;this.properties=properties;}@Scheduled(fixedDelayString="${luckyhub.fulfillment.poll-interval:5s}",initialDelayString="${luckyhub.fulfillment.initial-delay:60s}")public void poll(){state.recoverExpiredLeases(properties.recoveryBatchSize());worker.runCompensationBatch();}}
